INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('44f61885-86ce-4535-9767-417240b4fc3c'::uuid, '4e9d8165-2fe4-41cd-a0cf-28999f1635aa'::uuid, 'agent', 'Your Health Shield Basic policy covers inpatient hospitalization of 24 hours or more, with room rent up to Rs. 1,500 per day and ICU charges up to Rs. 3,000 per day. It also includes 30 days of pre-hospitalization, 60 days of post-hospitalization, over 200 day care procedures, and emergency ambulance services up to Rs. 1,500. The sum insured is Rs. 2,00,000 for individual plans or Rs. 3,00,000 for family floaters, with a 20% co-pay applicable. Is there anything else you can help with?', '2026-09-03T08:26:53.983220+00:00', 2) ON CONFLICT ("message_id") DO NOTHING;
