INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('928b2ab5-9d7b-427e-b9b2-649c448c4377'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'agent', 'A 20% co-pay means you are responsible for paying 20% of the eligible claim amount, while we cover the remaining 80%. For example, if your approved claim is Rs. 1,00,000, you would pay Rs. 20,000 and we would pay Rs. 80,000. Is there anything else you can help with?', '2026-09-03T08:30:51.338930+00:00', 2) ON CONFLICT ("message_id") DO NOTHING;
INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('0cf4a6cb-4f84-45cd-b327-d9f4da01d627'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'customer', 'so why this there should be mension of the 100% coverage then', '2026-09-03T08:31:30.850100+00:00', 3) ON CONFLICT ("message_id") DO NOTHING;
INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('33613959-1261-40d0-99e4-8a7adad1cd97'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'agent', 'I understand your frustration. The term "coverage" refers to the types of medical expenses included in the policy, not necessarily that the insurer pays 100% of the bill. Your Health Shield Basic plan has a mandatory 20% co-payment, which is a standard feature of this specific entry-level plan, unlike our Gold or Premium tiers which offer zero co-payment. Is there anything else you can help with?', '2026-09-03T08:31:33.421336+00:00', 3) ON CONFLICT ("message_id") DO NOTHING;
