INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('0241648a-5d8e-4332-83e4-319f842dc800'::uuid, '79268935-ea2b-4ed1-834e-7f6c289b9a73'::uuid, 'agent', 'Your Home Protector Elite policy provides comprehensive coverage including building damage up to Rs. 2 Crore and contents up to Rs. 25 Lakh, with new-for-old settlement for both. It also includes specific covers for jewellery up to Rs. 10 Lakh, fine art up to Rs. 5 Lakh, gadgets up to Rs. 3 Lakh worldwide, and personal liability up to Rs. 25 Lakh. Additional benefits include rent loss up to Rs. 50,000 per month, temporary accommodation up to Rs. 60,000, and appliance breakdown cover up to Rs. 1 Lakh per year. Is there anything else you would like to know?', '2026-09-04T06:36:14.822561+00:00', 2) ON CONFLICT ("message_id") DO NOTHING;
