INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('18afa7e0-3491-4cbe-b2fb-cfeadf676426'::uuid, '25f08c3a-d7f7-4fca-81ec-fecce4abb685'::uuid, 'customer', 'let suppose this policy cover bumperto bumper cover', '2026-09-04T08:16:34.091916+00:00', 1) ON CONFLICT ("message_id") DO NOTHING;
INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('a8f56a9c-6dd3-4a4c-b90e-444699d3aec1'::uuid, '25f08c3a-d7f7-4fca-81ec-fecce4abb685'::uuid, 'agent', 'Your current Motor Comprehensive plan does not include bumper-to-bumper cover by default. This coverage is available as an optional add-on called Zero Depreciation or Nil-Dep, which ensures no depreciation is deducted on replaced parts. Please note that this add-on is limited to a maximum of two claims per policy year and is only available for vehicles up to five years old. Would you like to know more about adding this to your policy?', '2026-09-04T08:16:36.345499+00:00', 1) ON CONFLICT ("message_id") DO NOTHING;
