INSERT INTO "message" ("message_id", "conversation_id", "role", "content", "timestamp", "turn_index") VALUES ('c97a10a1-1704-439b-ae6e-7452fc928411'::uuid, '25f08c3a-d7f7-4fca-81ec-fecce4abb685'::uuid, 'agent', 'To file a claim, please notify us within 48 hours of the accident via our helpline or app. You will need to provide details like the date, time, location, and nature of damage, along with documents such as your driving license, RC, policy copy, and photos of the damage. A surveyor will be assigned within 24 hours to inspect your vehicle, after which you can proceed with repairs at a network garage for cashless settlement. Is there anything else you can help with?', '2026-09-04T08:17:11.785798+00:00', 2) ON CONFLICT ("message_id") DO NOTHING;
