INSERT INTO "call_summary" ("summary_id", "conversation_id", "summary_text", "resolution", "escalated", "duration_sec", "tools_used", "generated_at") VALUES ('08857b5b-cc65-4049-a3ea-e91be64ef68c'::uuid, '52efce38-0b62-4096-80c5-5f0a339730af'::uuid, 'Policy-holder Amit inquired about the suspension of his Health Shield Basic policy, which was caused by a failed NACH auto-debit for an overdue invoice of Rs. 4,718.82 due on August 11, 2026. After discussing coverage details for inpatient surgeries and day-care procedures, Amit reported a recent major accident involving ligament, bone, and head injuries. The agent advised immediate payment of the outstanding premium to maintain coverage and escalated the claim inquiry to a human specialist with reference number ESC-909D2655.', 'escalated', TRUE, 0, '[]', '2026-09-02T06:11:06.310215+00:00') ON CONFLICT ("summary_id") DO NOTHING;
