INSERT INTO "call_summary" ("summary_id", "conversation_id", "summary_text", "resolution", "escalated", "duration_sec", "tools_used", "generated_at") VALUES ('06863830-7bc9-4641-8fb8-f3e86e253520'::uuid, 'ef2ae21b-d297-4fb7-8d74-692c2f83f444'::uuid, 'Policyholder Sneha inquired about the coverage details of her Home Protector Elite policy and the specific claim process for a recent theft incident. The agent verified that the policy covers building damage up to Rs. 2 Crore and contents up to Rs. 25 Lakh, with specific sub-limits for jewellery (Rs. 10 Lakh) and gadgets (Rs. 3 Lakh) on a new-for-old basis. The agent confirmed that theft coverage applies to both forced entry and sneak theft, contingent upon the submission of an FIR and police investigation report. No claim was formally filed, refund issued, or ticket created during this interaction, as the call concluded with general guidance on documentation requirements.', 'resolved', FALSE, 0, '[]', '2026-09-04T08:03:18.370619+00:00') ON CONFLICT ("summary_id") DO NOTHING;
