INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('40200c8e-23cd-4d79-b502-460edb2b231f'::uuid, 'c5bb88a7-cfd7-417e-82e2-4880d1ba769b'::uuid, 'get_policy_coverage', '{"query": "details related to my insurance plan", "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7"}', '{"plan": "Health Shield Gold", "found": true, "message": "Policy coverage details retrieved for Health Shield Gold from knowledge base.", "passages": [{"score": 0.766, "title": "Health Shield Gold Policy — General Terms", "domain": "health_insurance", "source": "health_shield_gold_policy.md", "content": "[Health Shield Gold Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}, {"score": 0.763, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Gold — Coverage Details]\nHealth Shield Gold is the mid-tier comprehensive plan with sum insured up to ₹10 Lakhs (family floater). No room rent sub-limit — full Private Single AC Room covered. ICU covered 100% with no cap. Includes 60-day pre-hospitalization, 90-day post-hospitalization, 540+ day care procedures, maternity (Normal delivery ₹75,000; C-section ₹1,00,000) after 24-month wait, newborn cover from Day 1 of birth, AYUSH treatment, 100% sum insured restoration once per year for a different illness, annual health"}, {"score": 0.752, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "health_insurance", "source": "health_shield_gold_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Health Shield Gold** is a comprehensive mid-tier health indemnity plan engineered for growing families, working professionals, and individuals seeking meaningful hospital coverage without coverage gaps. It eliminates room rent sub-limits, reduces waiting periods, and includes maternity coverage—a significant step up from Basic plans.\n\n**Key Specialty / USPs:**\n- **No room rent sub-limit** — Private Single AC Room covered in full\n- **Zero ICU cap** — 100% ICU charges reimbursed"}, {"score": 0.745, "title": "Health Shield Premium — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Premium cover that Gold does not?\nAnswer: Premium adds: OPD/outpatient coverage (₹15,000/year), mental health and psychiatric hospitalization, unlimited sum insured restoration (even for same illness), Critical Illness lump sum (₹5L on diagnosis), international emergency cover (₹10L), air ambulance (₹3L), HIV treatment, global medical second opinion, sum insured up to ₹1 Crore, and shortest PED waiting period of 12 months."}], "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7", "passage_count": 4}', 'success', 125, '2026-09-04T07:40:28.047573+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('67348e51-427a-4de9-8742-9d531f9f3eed'::uuid, '690f755b-b5c3-4056-99e4-54323e03d882'::uuid, 'get_policy_coverage', '{"query": "what kind of coverage will I get in case of theft?", "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90"}', '{"plan": "Home Protector Elite", "found": true, "message": "Policy coverage details retrieved for Home Protector Elite from knowledge base.", "passages": [{"score": 0.684, "title": "Home Protector Basic — Building and Contents Coverage", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "[Home Protector Basic — Building and Contents Coverage]\nis uninhabitable. Emergency repairs up to ₹5,000. Sneak theft (without forced entry) is NOT covered. Jewellery, gold, cash, motor vehicles, business goods, and pets are excluded. Settlement on Actual Cash Value (ACV — depreciated market value) basis."}, {"score": 0.683, "title": "Home Protector Elite — Premium Coverage Details", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "Question: Is my mobile phone and laptop covered if stolen outside the house?\nAnswer: Under Home Protector Elite''s Gadget Cover: Mobile phones, tablets, and laptops are covered for theft and accidental damage even outside the home — worldwide. Coverage: ₹1,50,000 per item, ₹3,00,000 total per year. Home Protector Basic only covers items inside the home."}, {"score": 0.671, "title": "Home Protector Elite — Premium Coverage Details", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "Question: What does Home Protector Elite cover that Basic does not?\nAnswer: Elite adds: New-for-Old settlement (no depreciation on contents/building), Building up to ₹2 Crore, Contents up to ₹25L, Jewellery up to ₹10L, Fine art ₹5L, Gadgets ₹3L worldwide, Sneak theft, Appliance breakdown (₹1L/yr without accident), Personal liability ₹25L, Global contents cover, Data recovery ₹25K, Architects fees, Debris removal, Rent loss ₹50K/month, and Temp accommodation ₹60K."}, {"score": 0.67, "title": "Home Protector Elite — Premium Coverage Details", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "[Home Protector Elite — Premium Coverage Details]\nHome Protector Elite covers all Basic perils plus: Building up to ₹2 Crore on full Reinstatement Value (New-for-Old, no depreciation). Accidental damage to building (pipe burst causing wall collapse, fixed glass breakage). Architects and surveyors fees for rebuild. Debris removal up to 5% of building sum insured. Rent loss up to ₹50,000/month for 6 months if property is rented out and becomes uninhabitable. Contents up to ₹25 Lakhs on New-for-Old basis. Jewellery and valuables up to ₹10 Lakhs."}], "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90", "passage_count": 4}', 'success', 110, '2026-09-04T08:06:13.945152+00:00') ON CONFLICT ("exec_id") DO NOTHING;
