INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('e7870345-239f-4526-a853-0b3b28042971'::uuid, '4e9d8165-2fe4-41cd-a0cf-28999f1635aa'::uuid, 'get_policy_coverage', '{"query": "what does my policy cover?", "customer_id": "c4a938ff-1913-47b3-ba90-6502a47669a2"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.759, "title": "Health Shield Basic Policy — General Terms", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[Health Shield Basic Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}, {"score": 0.725, "title": "SECTION 3: WHAT IS NOT COVERED (EXCLUSIONS) — 3.3 Permanent Exclusions", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[SECTION 3: WHAT IS NOT COVERED (EXCLUSIONS) — 3.3 Permanent Exclusions]\nThe following are never covered under Health Shield Basic:\n1. **Pre-existing diseases (PED)** in the first **36 months** of continuous coverage.\n2. Cosmetic, aesthetic, or reconstructive surgery (unless due to accidental burns or injuries).\n3. Dental treatment, unless requiring hospitalization due to accidental jaw fracture.\n4. Spectacles, contact lenses, hearing aids, orthopaedic implants for non-injury.\n5."}, {"score": 0.682, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Basic cover?\nAnswer: Health Shield Basic covers inpatient hospitalization (24+ hours), room rent up to ₹1,500/day, ICU up to ₹3,000/day, 30-day pre-hospitalization, 60-day post-hospitalization, 200+ day care procedures, and emergency ambulance up to ₹1,500. Sum insured: ₹2L (individual) or ₹3L (family floater). 20% co-pay applies."}, {"score": 0.673, "title": "Health Shield Premium Policy — General Terms", "domain": "health_insurance", "source": "health_shield_premium_policy.md", "content": "[Health Shield Premium Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}], "customer_id": "c4a938ff-1913-47b3-ba90-6502a47669a2", "passage_count": 4}', 'success', 218, '2026-09-03T08:26:52.625962+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('7ab56dd4-dc69-4995-8a96-76694273df0b'::uuid, 'ef2ae21b-d297-4fb7-8d74-692c2f83f444'::uuid, 'get_policy_coverage', '{"query": "What does my policy covers?", "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90"}', '{"plan": "Home Protector Elite", "found": true, "message": "Policy coverage details retrieved for Home Protector Elite from knowledge base.", "passages": [{"score": 0.747, "title": "Home Protector Elite — Premium Coverage Details", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "Question: What does Home Protector Elite cover that Basic does not?\nAnswer: Elite adds: New-for-Old settlement (no depreciation on contents/building), Building up to ₹2 Crore, Contents up to ₹25L, Jewellery up to ₹10L, Fine art ₹5L, Gadgets ₹3L worldwide, Sneak theft, Appliance breakdown (₹1L/yr without accident), Personal liability ₹25L, Global contents cover, Data recovery ₹25K, Architects fees, Debris removal, Rent loss ₹50K/month, and Temp accommodation ₹60K."}, {"score": 0.726, "title": "Home Protector Basic Policy — General Terms", "domain": "home_insurance", "source": "home_protector_basic_policy.md", "content": "[Home Protector Basic Policy — General Terms]\n# SECURESHIELD GENERAL INSURANCE COMPANY LIMITED"}, {"score": 0.719, "title": "Home Protector Elite Policy — General Terms", "domain": "home_insurance", "source": "home_protector_elite_policy.md", "content": "[Home Protector Elite Policy — General Terms]\n# SECURESHIELD GENERAL INSURANCE COMPANY LIMITED"}, {"score": 0.691, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "home_insurance", "source": "home_protector_elite_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Home Protector Elite** is the flagship, ultra-comprehensive home insurance plan from SecureShield — crafted for homeowners with high-value properties, luxury interiors, premium electronics, jewellery, art collections, and complete peace of mind requirements. This plan covers everything in the Basic plan and significantly extends protection to include jewellery, global contents cover, rent-loss liability, gadget cover, and a superior reinstatement value basis for all settlements."}], "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90", "passage_count": 4}', 'success', 109, '2026-09-04T07:41:45.995623+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('03d9f0fe-1d16-4628-9ffa-969c91684ba0'::uuid, '690f755b-b5c3-4056-99e4-54323e03d882'::uuid, 'escalate_to_human', '{"reason": "Dissatisfaction with automated response regarding theft claim process and coverage details.", "sentiment": "frustrated", "session_id": "2b82427a-2ad1-4819-8a6c-cd91e1670159", "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90", "conversation_id": "690f755b-b5c3-4056-99e4-54323e03d882", "customer_context": {"account": {"status": "active", "balance": 5014.41, "plan_name": "Home Protector Elite", "account_id": "649bb4cd-3f5d-40c4-a0bf-a10712b3fd07", "auto_renew": true, "data_used_gb": 389.2, "billing_cycle": "quarterly", "payment_method": "UPI"}, "customer": {"city": "Hyderabad", "name": "Sneha Reddy", "plan": "Home Protector Basic", "email": "sneha.reddy@email.com", "phone": "+91-9765432100", "state": "Telangana", "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90", "customer_tier": "elite", "account_number": "ACC-2024-004", "customer_since": "2020-11-30", "preferred_language": "en"}, "invoices": [{"period": "2026-07-02 – 2026-07-28", "status": "paid", "due_date": "2026-08-11", "amount_paid": 10028.82, "outstanding": 0.0, "total_amount": 10028.82, "invoice_number": "INV-2026-004006"}, {"period": "2026-06-02 – 2026-06-28", "status": "paid", "due_date": "2026-07-12", "amount_paid": 10028.82, "outstanding": 0.0, "total_amount": 10028.82, "invoice_number": "INV-2026-004005"}, {"period": "2026-05-03 – 2026-05-28", "status": "paid", "due_date": "2026-06-11", "amount_paid": 10028.82, "outstanding": 0.0, "total_amount": 10028.82, "invoice_number": "INV-2026-004004"}], "appointments": []}, "customer_profile": {"city": "Hyderabad", "name": "Sneha Reddy", "plan": "Home Protector Basic", "email": "sneha.reddy@email.com", "phone": "+91-9765432100", "state": "Telangana", "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90", "customer_tier": "elite", "account_number": "ACC-2024-004", "customer_since": "2020-11-30", "preferred_language": "en"}, "conversation_history": [{"role": "user", "content": "hi"}, {"role": "assistant", "content": "Hi Sneha, welcome to InsureAI. How can I help you today?"}, {"role": "user", "content": "What is my insurance policy?"}, {"role": "assistant", "content": "You are currently enrolled in the Home Protector Elite plan, which is active and billed quarterly via UPI. Your account balance is Rs.5,014.41. Is there anything else you would like to know about your policy?"}, {"role": "user", "content": " What does my policy covers?"}, {"role": "assistant", "content": "Your Home Protector Elite policy provides comprehensive coverage including building up to Rs.2 Crore, contents up to Rs.25 Lakh, and jewellery up to Rs.10 Lakh. It also includes global gadget cover, personal liability up to Rs.25 Lakh, rent loss up to Rs.50,000 per month, and temporary accommodation up to Rs.60,000. Would you like more details on any specific aspect?"}, {"role": "user", "content": "I just had a theft in my house and I want to know the process of applying for the claim. Also in case of theft what kind of coverage will I get?"}, {"role": "assistant", "content": "I am sorry to hear about the theft. Your Home Protector Elite policy covers theft, including sneak theft without forced entry, with contents settled on a New-for-Old basis up to Rs.25 Lakhs and jewellery up to Rs.10 Lakhs. To file a claim, you must first report the incident to the police and obtain a First Information Report, then contact us immediately to initiate the claim process. Is there anything else you need help with?"}]}', '{"message": "I''ve connected you with our support team immediately. Agent Deepa Krishnamurthy is reviewing your case now. Ref: ESC-08F7F082.", "success": true, "priority": "high", "scheduled_at": "2026-09-04T08:07:00.549724+00:00", "wait_minutes": 0, "agent_assigned": "Deepa Krishnamurthy", "appointment_id": "22c96217-28e0-456d-b38a-e1d82ffea868", "appointment_number": "ESC-08F7F082"}', 'success', 109, '2026-09-04T08:07:00.633888+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('a733408e-5112-4c0a-9375-6a9490bffeca'::uuid, '25f08c3a-d7f7-4fca-81ec-fecce4abb685'::uuid, 'get_policy_coverage', '{"query": "what does motor comprehensive cover for bumper to bumper cover?", "customer_id": "5be8c3e2-232c-4731-aae5-4669293f6958"}', '{"plan": "Motor Comprehensive", "found": true, "message": "Policy coverage details retrieved for Motor Comprehensive from knowledge base.", "passages": [{"score": 0.579, "title": "Motor Comprehensive Plus — All Bundled Benefits", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "Question: What does Comprehensive Plus motor insurance cover?\nAnswer: Everything in Comprehensive PLUS Zero Dep (unlimited claims), Engine/Gearbox Protection, Return to Invoice on total loss/theft, Consumables Cover, Tyre Protect (4 tyres/year), Key & Lock Replacement (₹25K/year), Enhanced RSA (100km tow, hotel benefit, hire car ₹1,500/day), NCB Protection, and Enhanced PA of ₹25 Lakhs. EV battery covered up to ₹5 Lakhs."}, {"score": 0.549, "title": "Motor Comprehensive Policy — Coverage and Add-Ons", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "Question: What is covered under Comprehensive motor insurance?\nAnswer: Own vehicle damage from: accidents, fire, explosion, theft, burglary, riots, vandalism, floods, cyclone, earthquake, hailstorm, landslide, and transit damage. PLUS all Third Party liability (injury/death/property) and PA cover for the owner-driver. Add-ons like Zero Dep, Engine Protect, RTI are optional extras."}, {"score": 0.541, "title": "Motor Comprehensive Plus — All Bundled Benefits", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "[Motor Comprehensive Plus — All Bundled Benefits]\nComprehensive Plus is the premium motor plan that bundles all add-ons as standard: Zero Depreciation (unlimited claims, no 2-claim limit), Engine & Gearbox Protection (hydrostatic lock covered), Return to Invoice on CTL or theft (original invoice price paid), Consumables Cover (oil, bolts, coolant), Tyre Protect (4 tyres/year), Key & Lock Replacement (₹25,000/year), Extended RSA (100km towing, hotel stay, hire car), NCB Protection (1 free claim/year without NCB reset), and Enhanced PA ₹25 Lakhs"}, {"score": 0.522, "title": "SECTION 5: STANDARD ADD-ONS AVAILABLE WITH COMPREHENSIVE PLAN — Add-On 1: Zero Depreciation (Nil-Dep / Bumper-to-Bumper Cover)", "domain": "motor_insurance", "source": "motor_comprehensive_policy.md", "content": "[SECTION 5: STANDARD ADD-ONS AVAILABLE WITH COMPREHENSIVE PLAN — Add-On 1: Zero Depreciation (Nil-Dep / Bumper-to-Bumper Cover)]\n- No depreciation deducted on any replaced parts.\n- Full part replacement at 100% cost — only compulsory deductible payable.\n- Maximum **2 Zero Dep claims** per policy year.\n- Available for vehicles up to **5 years old**."}], "customer_id": "5be8c3e2-232c-4731-aae5-4669293f6958", "passage_count": 4}', 'success', 219, '2026-09-04T08:16:35.425219+00:00') ON CONFLICT ("exec_id") DO NOTHING;
