INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('e51b9d04-4b7d-46b3-b6a1-de1730515412'::uuid, '4e9d8165-2fe4-41cd-a0cf-28999f1635aa'::uuid, 'get_policy_coverage', '{"query": "what kind of bed is provided in my policy", "customer_id": "c4a938ff-1913-47b3-ba90-6502a47669a2"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.611, "title": "Health Shield Basic Policy — General Terms", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[Health Shield Basic Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}, {"score": 0.603, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Basic cover?\nAnswer: Health Shield Basic covers inpatient hospitalization (24+ hours), room rent up to ₹1,500/day, ICU up to ₹3,000/day, 30-day pre-hospitalization, 60-day post-hospitalization, 200+ day care procedures, and emergency ambulance up to ₹1,500. Sum insured: ₹2L (individual) or ₹3L (family floater). 20% co-pay applies."}, {"score": 0.577, "title": "SECTION 3: WHAT IS NOT COVERED (EXCLUSIONS) — 3.3 Permanent Exclusions", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[SECTION 3: WHAT IS NOT COVERED (EXCLUSIONS) — 3.3 Permanent Exclusions]\nThe following are never covered under Health Shield Basic:\n1. **Pre-existing diseases (PED)** in the first **36 months** of continuous coverage.\n2. Cosmetic, aesthetic, or reconstructive surgery (unless due to accidental burns or injuries).\n3. Dental treatment, unless requiring hospitalization due to accidental jaw fracture.\n4. Spectacles, contact lenses, hearing aids, orthopaedic implants for non-injury.\n5."}, {"score": 0.572, "title": "Room Rent Coverage and Hospital Room Categories", "domain": "health_insurance", "source": "health_insurance_kb.json", "content": "Question: What hospital bed category is covered?\nAnswer: Health Gold covers Single Private AC Room bed category. You are entitled to a private air-conditioned room during hospitalization. ICU beds have no daily charge limit. Choosing a ward or shared room would be entirely covered."}], "customer_id": "c4a938ff-1913-47b3-ba90-6502a47669a2", "passage_count": 4}', 'success', 140, '2026-09-03T08:27:12.596731+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('aa2db8a4-fdc8-461d-b7cb-a4e9b98b3284'::uuid, '6344cc94-1f2a-4719-a0f5-1684a1312078'::uuid, 'get_policy_coverage', '{"query": "how to claim hospital bills and motor full service for major accident", "customer_id": "85820d3a-750c-47e0-942b-92474167bcd5"}', '{"plan": "Motor Comprehensive Plus", "found": true, "message": "Policy coverage details retrieved for Motor Comprehensive Plus from knowledge base.", "passages": [{"score": 0.617, "title": "Motor Insurance Claims Process — Steps and Documents", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "Question: How do I claim motor insurance after an accident?\nAnswer: Step 1: Notify SecureShield within 48 hours (24 hrs for Comprehensive Plus) via helpline. Step 2: Surveyor is appointed within 24 hours. Step 3: Take vehicle to cashless network garage or get surveyor approval for non-network repairs. Step 4: Insurer pays the garage directly (cashless) or reimburses you within 7–10 days (non-network)."}, {"score": 0.596, "title": "Motor Insurance Claim Filing Process", "domain": "motor_insurance", "source": "motor_insurance_kb.json", "content": "Question: What documents are needed for a motor insurance claim?\nAnswer: You need: (1) Claim intimation form, (2) Copy of driving license, (3) Copy of RC (Registration Certificate), (4) Copy of insurance policy, (5) FIR copy (for theft or third-party injury), (6) Repair estimates and bills, (7) Photographs of the damage."}, {"score": 0.587, "title": "Motor Comprehensive Policy — Coverage and Add-Ons", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "Question: What is covered under Comprehensive motor insurance?\nAnswer: Own vehicle damage from: accidents, fire, explosion, theft, burglary, riots, vandalism, floods, cyclone, earthquake, hailstorm, landslide, and transit damage. PLUS all Third Party liability (injury/death/property) and PA cover for the owner-driver. Add-ons like Zero Dep, Engine Protect, RTI are optional extras."}, {"score": 0.586, "title": "Motor Insurance Claims Process — Steps and Documents", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "Question: What documents are required for a motor insurance claim?\nAnswer: Required: (1) FIR copy (for theft, third-party accidents), (2) Driving licence of driver at time of accident, (3) Vehicle Registration Certificate (RC), (4) Original repair invoice and parts bill, (5) Survey report, (6) Claim form filled and signed, (7) Bank details for reimbursement."}], "customer_id": "85820d3a-750c-47e0-942b-92474167bcd5", "passage_count": 4}', 'success', 109, '2026-09-03T08:38:02.336165+00:00') ON CONFLICT ("exec_id") DO NOTHING;
