INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('3926cfab-a4ac-477e-a5dd-24a24ffd7b23'::uuid, 'ef2ae21b-d297-4fb7-8d74-692c2f83f444'::uuid, 'get_policy_coverage', '{"query": "what kind of coverage will I get in case of theft and what is the process of applying for the claim?", "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90"}', '{"plan": "Home Protector Elite", "found": true, "message": "Policy coverage details retrieved for Home Protector Elite from knowledge base.", "passages": [{"score": 0.644, "title": "Home Protector Elite — Premium Coverage Details", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "[Home Protector Elite — Premium Coverage Details]\nHome Protector Elite covers all Basic perils plus: Building up to ₹2 Crore on full Reinstatement Value (New-for-Old, no depreciation). Accidental damage to building (pipe burst causing wall collapse, fixed glass breakage). Architects and surveyors fees for rebuild. Debris removal up to 5% of building sum insured. Rent loss up to ₹50,000/month for 6 months if property is rented out and becomes uninhabitable. Contents up to ₹25 Lakhs on New-for-Old basis. Jewellery and valuables up to ₹10 Lakhs."}, {"score": 0.641, "title": "SECTION 2: WHAT IS COVERED — 2.4 Sneak Theft (Without Forced Entry)", "domain": "home_insurance", "source": "home_protector_elite_policy.md", "content": "[SECTION 2: WHAT IS COVERED — 2.4 Sneak Theft (Without Forced Entry)]\nUnlike the Basic plan, **Home Protector Elite** covers theft even when no forced entry (break-in) is evident — including:\n- Theft by domestic workers (maid, cook, driver) where FIR is filed.\n- Opportunistic theft when a door/window was left open.\n- Subject to FIR and Police investigation report being submitted."}, {"score": 0.64, "title": "Home Protector Elite — Premium Coverage Details", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "Question: What does Home Protector Elite cover that Basic does not?\nAnswer: Elite adds: New-for-Old settlement (no depreciation on contents/building), Building up to ₹2 Crore, Contents up to ₹25L, Jewellery up to ₹10L, Fine art ₹5L, Gadgets ₹3L worldwide, Sneak theft, Appliance breakdown (₹1L/yr without accident), Personal liability ₹25L, Global contents cover, Data recovery ₹25K, Architects fees, Debris removal, Rent loss ₹50K/month, and Temp accommodation ₹60K."}, {"score": 0.639, "title": "Home Protector Basic — Building and Contents Coverage", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "[Home Protector Basic — Building and Contents Coverage]\nis uninhabitable. Emergency repairs up to ₹5,000. Sneak theft (without forced entry) is NOT covered. Jewellery, gold, cash, motor vehicles, business goods, and pets are excluded. Settlement on Actual Cash Value (ACV — depreciated market value) basis."}], "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90", "passage_count": 4}', 'success', 125, '2026-09-04T07:42:05.240886+00:00') ON CONFLICT ("exec_id") DO NOTHING;
