INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('e4a73290-0fc2-4700-b79e-2ff2a1d74a71'::uuid, '4e9d8165-2fe4-41cd-a0cf-28999f1635aa'::uuid, 'get_policy_coverage', '{"query": "what kind of room or bed is provided by my policy?", "customer_id": "c4a938ff-1913-47b3-ba90-6502a47669a2"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.627, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Basic cover?\nAnswer: Health Shield Basic covers inpatient hospitalization (24+ hours), room rent up to ₹1,500/day, ICU up to ₹3,000/day, 30-day pre-hospitalization, 60-day post-hospitalization, 200+ day care procedures, and emergency ambulance up to ₹1,500. Sum insured: ₹2L (individual) or ₹3L (family floater). 20% co-pay applies."}, {"score": 0.619, "title": "Room Rent Coverage and Hospital Room Categories", "domain": "health_insurance", "source": "health_insurance_kb.json", "content": "Question: What hospital bed category is covered?\nAnswer: Health Gold covers Single Private AC Room bed category. You are entitled to a private air-conditioned room during hospitalization. ICU beds have no daily charge limit. Choosing a ward or shared room would be entirely covered."}, {"score": 0.583, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "health_insurance", "source": "health_shield_gold_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Health Shield Gold** is a comprehensive mid-tier health indemnity plan engineered for growing families, working professionals, and individuals seeking meaningful hospital coverage without coverage gaps. It eliminates room rent sub-limits, reduces waiting periods, and includes maternity coverage—a significant step up from Basic plans.\n\n**Key Specialty / USPs:**\n- **No room rent sub-limit** — Private Single AC Room covered in full\n- **Zero ICU cap** — 100% ICU charges reimbursed"}, {"score": 0.573, "title": "Health Shield Basic Policy — General Terms", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[Health Shield Basic Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}], "customer_id": "c4a938ff-1913-47b3-ba90-6502a47669a2", "passage_count": 4}', 'success', 125, '2026-09-03T08:27:59.994015+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('584885c5-5e98-4481-aaaa-41718f66cf7b'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'get_policy_coverage', '{"query": "Does Health Shield Basic plan offer 100% coverage or is there a 20% co-pay? What are the exact coverage terms and exclusions for inpatient surgery?", "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.705, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Health Shield Basic** is an affordable entry-level individual and family health indemnity plan designed for first-time insurance buyers, young professionals, and price-conscious families. It covers essential inpatient hospitalization expenses with straightforward terms and a wide cashless hospital network.\n\n**Key Specialty:**\n- Low-cost quarterly premium with no annual lump-sum burden\n- Covers all major acute and chronic illnesses after applicable waiting periods"}, {"score": 0.699, "title": "Health Shield Plan Comparison — Basic vs Gold vs Premium", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: Does Health Shield Basic have co-payment?\nAnswer: Yes, Health Shield Basic has a mandatory 20% co-payment on every claim. This means if the eligible claim is ₹1,00,000, you pay ₹20,000 and the insurer pays ₹80,000. Health Shield Gold and Premium have zero co-payment."}, {"score": 0.697, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Basic cover?\nAnswer: Health Shield Basic covers inpatient hospitalization (24+ hours), room rent up to ₹1,500/day, ICU up to ₹3,000/day, 30-day pre-hospitalization, 60-day post-hospitalization, 200+ day care procedures, and emergency ambulance up to ₹1,500. Sum insured: ₹2L (individual) or ₹3L (family floater). 20% co-pay applies."}, {"score": 0.685, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Basic — Coverage Details]\nHealth Shield Basic covers inpatient hospitalization for at least 24 hours with room rent up to ₹1,500 per day, ICU up to ₹3,000 per day, and surgeon/specialist fees in full. Pre-hospitalization covered for 30 days and post-hospitalization for 60 days. Includes 200+ day care procedures (cataract, chemotherapy, dialysis, tonsillectomy). Emergency ambulance up to ₹1,500. Sum insured options: ₹2 Lakhs individual, ₹3 Lakhs family floater. Cumulative bonus 10% per claim-free year."}], "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7", "passage_count": 4}', 'success', 156, '2026-09-03T08:31:32.510968+00:00') ON CONFLICT ("exec_id") DO NOTHING;
