INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('b619368f-1172-43a4-98cc-388d341370c1'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'get_policy_coverage', '{"query": "which surgery will cover in this plan like i have surgery regarding legament will it cover?", "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.647, "title": "Cancer, Heart, and Neurological Coverage", "domain": "health_insurance", "source": "health_scenarios_kb.json", "content": "[Cancer, Heart, and Neurological Coverage]\nCancer in all stages is covered under all Health Shield plans — including surgery, chemotherapy (as day care), radiotherapy, targeted therapy (biologic agents), and ICU care post-surgery. Pre-hospitalization oncology consultations, biopsy, PET scan, and MRI are covered. Health Shield Premium includes Critical Illness lump sum of ₹5 Lakhs on first diagnosis."}, {"score": 0.622, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Basic — Coverage Details]\nHealth Shield Basic covers inpatient hospitalization for at least 24 hours with room rent up to ₹1,500 per day, ICU up to ₹3,000 per day, and surgeon/specialist fees in full. Pre-hospitalization covered for 30 days and post-hospitalization for 60 days. Includes 200+ day care procedures (cataract, chemotherapy, dialysis, tonsillectomy). Emergency ambulance up to ₹1,500. Sum insured options: ₹2 Lakhs individual, ₹3 Lakhs family floater. Cumulative bonus 10% per claim-free year."}, {"score": 0.616, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Basic cover?\nAnswer: Health Shield Basic covers inpatient hospitalization (24+ hours), room rent up to ₹1,500/day, ICU up to ₹3,000/day, 30-day pre-hospitalization, 60-day post-hospitalization, 200+ day care procedures, and emergency ambulance up to ₹1,500. Sum insured: ₹2L (individual) or ₹3L (family floater). 20% co-pay applies."}, {"score": 0.616, "title": "Orthopaedic, Bone, and Spine Surgery Coverage", "domain": "health_insurance", "source": "health_scenarios_kb.json", "content": "Question: Is spine surgery (back surgery) covered?\nAnswer: Yes. Spinal disc surgeries (discectomy, TLIF, PLIF, laminectomy) are covered under all Health Shield plans after the initial 30-day waiting period. Spinal cord compression surgery and vertebroplasty are also covered."}], "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7", "passage_count": 4}', 'success', 125, '2026-09-03T08:30:12.745814+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('b4222da9-1682-475e-81cf-9ffe0f5715c9'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'get_policy_coverage', '{"query": "what mean by 20% co-pay?", "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.746, "title": "Health Shield Plan Comparison — Basic vs Gold vs Premium", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: Does Health Shield Basic have co-payment?\nAnswer: Yes, Health Shield Basic has a mandatory 20% co-payment on every claim. This means if the eligible claim is ₹1,00,000, you pay ₹20,000 and the insurer pays ₹80,000. Health Shield Gold and Premium have zero co-payment."}, {"score": 0.647, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Basic — Coverage Details]\nfloater. Cumulative bonus 10% per claim-free year. No maternity cover. 36-month PED waiting period. 20% co-payment on all claims."}, {"score": 0.627, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Basic cover?\nAnswer: Health Shield Basic covers inpatient hospitalization (24+ hours), room rent up to ₹1,500/day, ICU up to ₹3,000/day, 30-day pre-hospitalization, 60-day post-hospitalization, 200+ day care procedures, and emergency ambulance up to ₹1,500. Sum insured: ₹2L (individual) or ₹3L (family floater). 20% co-pay applies."}, {"score": 0.6, "title": "Health Shield Premium — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Premium — Coverage Details]\n₹10 Lakhs, air ambulance up to ₹3 Lakhs, unlimited sum insured restoration (even for same illness), annual health check-up up to ₹10,000, global second medical opinion once per year, HIV treatment covered, and dedicated relationship manager. Zero co-pay. 12-month PED waiting period."}], "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7", "passage_count": 4}', 'success', 110, '2026-09-03T08:30:50.189394+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('259f8d2d-7910-4e54-ab42-f95ae4a83ae1'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'get_policy_coverage', '{"query": "how to claim bone surgery of 5 lac", "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7"}', '{"plan": "Health Shield Gold", "found": true, "message": "Policy coverage details retrieved for Health Shield Gold from knowledge base.", "passages": [{"score": 0.544, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Gold — Coverage Details]\nHealth Shield Gold is the mid-tier comprehensive plan with sum insured up to ₹10 Lakhs (family floater). No room rent sub-limit — full Private Single AC Room covered. ICU covered 100% with no cap. Includes 60-day pre-hospitalization, 90-day post-hospitalization, 540+ day care procedures, maternity (Normal delivery ₹75,000; C-section ₹1,00,000) after 24-month wait, newborn cover from Day 1 of birth, AYUSH treatment, 100% sum insured restoration once per year for a different illness, annual health"}, {"score": 0.528, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Gold cover?\nAnswer: Gold covers: inpatient hospitalization (Private AC Room, no sub-limit), ICU at 100%, 60-day pre-hospitalization, 90-day post-hospitalization, 540+ day care procedures, maternity (₹75K normal/₹1L C-section after 24 months), newborn from Day 1, AYUSH, ambulance ₹5,000, annual check-up, and 100% sum insured restoration. Zero co-pay, sum insured up to ₹10L."}, {"score": 0.52, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Gold — Coverage Details]\nce per year for a different illness, annual health check-up up to ₹2,500, and ambulance up to ₹5,000. Zero co-payment. 24-month PED waiting period."}, {"score": 0.508, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "health_insurance", "source": "health_shield_gold_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Health Shield Gold** is a comprehensive mid-tier health indemnity plan engineered for growing families, working professionals, and individuals seeking meaningful hospital coverage without coverage gaps. It eliminates room rent sub-limits, reduces waiting periods, and includes maternity coverage—a significant step up from Basic plans.\n\n**Key Specialty / USPs:**\n- **No room rent sub-limit** — Private Single AC Room covered in full\n- **Zero ICU cap** — 100% ICU charges reimbursed"}], "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7", "passage_count": 4}', 'success', 125, '2026-09-03T08:34:11.789158+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('41725eb8-8513-44cc-9729-38e2537ab45b'::uuid, '25f08c3a-d7f7-4fca-81ec-fecce4abb685'::uuid, 'get_policy_coverage', '{"query": "how can i claim one accident here so how can i claim", "customer_id": "5be8c3e2-232c-4731-aae5-4669293f6958"}', '{"plan": "Motor Comprehensive", "found": true, "message": "Policy coverage details retrieved for Motor Comprehensive from knowledge base.", "passages": [{"score": 0.672, "title": "Motor Insurance Claims Process — Steps and Documents", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "Question: How do I claim motor insurance after an accident?\nAnswer: Step 1: Notify SecureShield within 48 hours (24 hrs for Comprehensive Plus) via helpline. Step 2: Surveyor is appointed within 24 hours. Step 3: Take vehicle to cashless network garage or get surveyor approval for non-network repairs. Step 4: Insurer pays the garage directly (cashless) or reimburses you within 7–10 days (non-network)."}, {"score": 0.665, "title": "Motor Insurance Claim Filing Process", "domain": "motor_insurance", "source": "motor_insurance_kb.json", "content": "Question: How do I file a motor insurance claim?\nAnswer: Report the incident to your insurer within 48 hours by calling the helpline. Provide accident details and damage description. A surveyor will be assigned within 24 hours to inspect the vehicle. Take the vehicle to a network garage for cashless repairs, or any garage for reimbursement claims."}, {"score": 0.653, "title": "Motor Insurance Claim Filing Process", "domain": "motor_insurance", "source": "motor_insurance_kb.json", "content": "[Motor Insurance Claim Filing Process]\nStep-by-step process to file a motor insurance claim: Step 1 — Report the incident to the insurer within 48 hours of the accident by calling the helpline or using the app. Step 2 — Provide details including date, time, and location of the incident, nature of damage, and FIR number (if applicable for theft or third-party injury). Step 3 — A certified surveyor is appointed by the insurer within 24 hours to inspect the vehicle damage."}, {"score": 0.627, "title": "Motor Insurance Claim Filing Process", "domain": "motor_insurance", "source": "motor_insurance_kb.json", "content": "Question: What documents are needed for a motor insurance claim?\nAnswer: You need: (1) Claim intimation form, (2) Copy of driving license, (3) Copy of RC (Registration Certificate), (4) Copy of insurance policy, (5) FIR copy (for theft or third-party injury), (6) Repair estimates and bills, (7) Photographs of the damage."}], "customer_id": "5be8c3e2-232c-4731-aae5-4669293f6958", "passage_count": 4}', 'success', 92, '2026-09-04T08:17:10.790874+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('82d9ebfd-1d4a-4e32-9bca-d93b78cc0715'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'get_policy_coverage', '{"query": "how much extra i have to pay to shift to the gold plan", "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.721, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "health_insurance", "source": "health_shield_gold_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Health Shield Gold** is a comprehensive mid-tier health indemnity plan engineered for growing families, working professionals, and individuals seeking meaningful hospital coverage without coverage gaps. It eliminates room rent sub-limits, reduces waiting periods, and includes maternity coverage—a significant step up from Basic plans.\n\n**Key Specialty / USPs:**\n- **No room rent sub-limit** — Private Single AC Room covered in full\n- **Zero ICU cap** — 100% ICU charges reimbursed"}, {"score": 0.715, "title": "Health Shield Plan Comparison — Basic vs Gold vs Premium", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Plan Comparison — Basic vs Gold vs Premium]\nSecureShield offers three Health Shield plans: Basic (₹3,999/quarter), Gold (₹7,499/quarter), and Premium (₹14,999/quarter). Basic plan offers sum insured up to ₹3 Lakhs with 20% co-payment, room rent capped at ₹1,500/day, no maternity, and 36-month PED waiting period. Gold plan offers sum insured up to ₹10 Lakhs, no room rent sub-limit (Private AC Room), no co-payment, maternity included (after 24 months), and 24-month PED waiting period."}, {"score": 0.714, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Gold — Coverage Details]\nHealth Shield Gold is the mid-tier comprehensive plan with sum insured up to ₹10 Lakhs (family floater). No room rent sub-limit — full Private Single AC Room covered. ICU covered 100% with no cap. Includes 60-day pre-hospitalization, 90-day post-hospitalization, 540+ day care procedures, maternity (Normal delivery ₹75,000; C-section ₹1,00,000) after 24-month wait, newborn cover from Day 1 of birth, AYUSH treatment, 100% sum insured restoration once per year for a different illness, annual health"}, {"score": 0.689, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Gold — Coverage Details]\nce per year for a different illness, annual health check-up up to ₹2,500, and ambulance up to ₹5,000. Zero co-payment. 24-month PED waiting period."}], "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7", "passage_count": 4}', 'success', 125, '2026-09-03T08:32:24.561872+00:00') ON CONFLICT ("exec_id") DO NOTHING;
