INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('1e7f8741-7365-48f0-bbdf-a062d53f922a'::uuid, '5c517293-e2e1-4972-a3ae-ce6d53f57d36'::uuid, 'get_policy_coverage', '{"query": "which bed admit i have allow", "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7"}', '{"plan": "Health Shield Gold", "found": true, "message": "Policy coverage details retrieved for Health Shield Gold from knowledge base.", "passages": [{"score": 0.628, "title": "Room Rent Coverage and Hospital Room Categories", "domain": "health_insurance", "source": "health_insurance_kb.json", "content": "Question: What hospital bed category is covered?\nAnswer: Health Gold covers Single Private AC Room bed category. You are entitled to a private air-conditioned room during hospitalization. ICU beds have no daily charge limit. Choosing a ward or shared room would be entirely covered."}, {"score": 0.623, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "health_insurance", "source": "health_shield_gold_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Health Shield Gold** is a comprehensive mid-tier health indemnity plan engineered for growing families, working professionals, and individuals seeking meaningful hospital coverage without coverage gaps. It eliminates room rent sub-limits, reduces waiting periods, and includes maternity coverage—a significant step up from Basic plans.\n\n**Key Specialty / USPs:**\n- **No room rent sub-limit** — Private Single AC Room covered in full\n- **Zero ICU cap** — 100% ICU charges reimbursed"}, {"score": 0.593, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Gold cover?\nAnswer: Gold covers: inpatient hospitalization (Private AC Room, no sub-limit), ICU at 100%, 60-day pre-hospitalization, 90-day post-hospitalization, 540+ day care procedures, maternity (₹75K normal/₹1L C-section after 24 months), newborn from Day 1, AYUSH, ambulance ₹5,000, annual check-up, and 100% sum insured restoration. Zero co-pay, sum insured up to ₹10L."}, {"score": 0.587, "title": "Health Shield Gold — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "[Health Shield Gold — Coverage Details]\nHealth Shield Gold is the mid-tier comprehensive plan with sum insured up to ₹10 Lakhs (family floater). No room rent sub-limit — full Private Single AC Room covered. ICU covered 100% with no cap. Includes 60-day pre-hospitalization, 90-day post-hospitalization, 540+ day care procedures, maternity (Normal delivery ₹75,000; C-section ₹1,00,000) after 24-month wait, newborn cover from Day 1 of birth, AYUSH treatment, 100% sum insured restoration once per year for a different illness, annual health"}], "customer_id": "f15c45e9-9d47-4364-a95c-0586bf48f9b7", "passage_count": 4}', 'success', 109, '2026-09-03T08:33:30.163642+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('60a52cb9-78c8-4e17-907f-9b0de73bd6ee'::uuid, '6344cc94-1f2a-4719-a0f5-1684a1312078'::uuid, 'get_policy_coverage', '{"query": "what claims can I claim with this policy for car accident damage and personal injury hospital bills", "customer_id": "85820d3a-750c-47e0-942b-92474167bcd5"}', '{"plan": "Motor Comprehensive Plus", "found": true, "message": "Policy coverage details retrieved for Motor Comprehensive Plus from knowledge base.", "passages": [{"score": 0.724, "title": "Motor Comprehensive Policy — Coverage and Add-Ons", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "[Motor Comprehensive Policy — Coverage and Add-Ons]\nComprehensive motor insurance covers own vehicle loss or damage from: accidents/collision, fire/explosion, theft, riot/vandalism, natural disasters (flood, earthquake, cyclone, hailstorm, landslide), and transit damage. The Insured Declared Value (IDV) is the maximum own-damage claim payable. For partial loss, depreciation is deducted on parts (50% on rubber/plastic, 5–50% on metal based on age). Vehicle is declared Total Loss or CTL when repair cost exceeds 75% of IDV."}, {"score": 0.718, "title": "SECTION 1: WHAT IS COVERED — 1.1 Third-Party Bodily Injury & Death (Unlimited Liability)", "domain": "motor_insurance", "source": "motor_third_party_policy.md", "content": "[SECTION 1: WHAT IS COVERED — 1.1 Third-Party Bodily Injury & Death (Unlimited Liability)]\nThe Company indemnifies the Insured for **all sums legally payable** to a third party (pedestrian, cyclist, vehicle occupant of another vehicle, or any other person not in the insured vehicle) as compensation for:\n1. **Death** caused by or arising out of the use of the insured vehicle.\n2. **Bodily Injury** — including fractures, permanent disability, temporary disability, or grievous hurt.\n3. Compensation is determined by:\n   - **Motor Accident Claims Tribunal (MACT)** or a Court of Law."}, {"score": 0.703, "title": "Motor Comprehensive Policy — Coverage and Add-Ons", "domain": "motor_insurance", "source": "motor_plans_kb.json", "content": "Question: What is covered under Comprehensive motor insurance?\nAnswer: Own vehicle damage from: accidents, fire, explosion, theft, burglary, riots, vandalism, floods, cyclone, earthquake, hailstorm, landslide, and transit damage. PLUS all Third Party liability (injury/death/property) and PA cover for the owner-driver. Add-ons like Zero Dep, Engine Protect, RTI are optional extras."}, {"score": 0.699, "title": "Common Accident and Damage Scenarios", "domain": "motor_insurance", "source": "motor_scenarios_kb.json", "content": "[Common Accident and Damage Scenarios]\nScenario: Car parked on road, hit by another vehicle — Own damage is covered under Comprehensive insurance. File FIR only if the at-fault vehicle is identified (for third-party recovery). Scenario: Car hit a pothole and damaged axle — Own damage from road accident is covered under Comprehensive. Scenario: Scratched while parking in a tight spot — Own damage covered; minor dents and scratches from parking accidents are claimable. However, frequent small claims affect NCB."}], "customer_id": "85820d3a-750c-47e0-942b-92474167bcd5", "passage_count": 4}', 'success', 93, '2026-09-03T08:40:30.976050+00:00') ON CONFLICT ("exec_id") DO NOTHING;
