INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('0872085d-ea28-4509-b321-0cab7cdf48d0'::uuid, '36ef8e9d-94e2-4edc-bfa3-0a8e4ce0909c'::uuid, 'get_policy_coverage', '{"query": "Can you provide details about the coverage of my insurance policy.", "customer_id": "595b04b4-92bb-44ad-9b64-7adea210fddb"}', '{"plan": "Health Shield Premium", "found": true, "message": "Policy coverage details retrieved for Health Shield Premium from knowledge base.", "passages": [{"score": 0.707, "title": "Health Shield Premium Policy — General Terms", "domain": "health_insurance", "source": "health_shield_premium_policy.md", "content": "[Health Shield Premium Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}, {"score": 0.66, "title": "Health Shield Basic Policy — General Terms", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[Health Shield Basic Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}, {"score": 0.641, "title": "Cancer, Heart, and Neurological Coverage", "domain": "health_insurance", "source": "health_scenarios_kb.json", "content": "[Cancer, Heart, and Neurological Coverage]\nCancer in all stages is covered under all Health Shield plans — including surgery, chemotherapy (as day care), radiotherapy, targeted therapy (biologic agents), and ICU care post-surgery. Pre-hospitalization oncology consultations, biopsy, PET scan, and MRI are covered. Health Shield Premium includes Critical Illness lump sum of ₹5 Lakhs on first diagnosis."}, {"score": 0.621, "title": "Renewal, Portability, and Policy Management", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: When is health insurance premium due?\nAnswer: Health Shield premiums are payable quarterly (every 3 months). The quarterly amounts are: Basic ₹3,999, Gold ₹7,499, and Premium ₹14,999 (before GST of 18%)."}], "customer_id": "595b04b4-92bb-44ad-9b64-7adea210fddb", "passage_count": 4}', 'success', 219, '2026-09-21T04:40:43.970586+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('7a0e8ba3-5b4d-46bc-9e19-ae3d431f4b42'::uuid, 'a2d17072-475d-4c2d-aa11-1f3ef67d377d'::uuid, 'get_policy_coverage', '{"query": "can you provide detail about my policy coverage?", "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90"}', '{"plan": "Home Protector Elite", "found": true, "message": "Policy coverage details retrieved for Home Protector Elite from knowledge base.", "passages": [{"score": 0.735, "title": "Home Protector Elite Policy — General Terms", "domain": "home_insurance", "source": "home_protector_elite_policy.md", "content": "[Home Protector Elite Policy — General Terms]\n# SECURESHIELD GENERAL INSURANCE COMPANY LIMITED"}, {"score": 0.728, "title": "Home Protector Basic Policy — General Terms", "domain": "home_insurance", "source": "home_protector_basic_policy.md", "content": "[Home Protector Basic Policy — General Terms]\n# SECURESHIELD GENERAL INSURANCE COMPANY LIMITED"}, {"score": 0.689, "title": "Home Protector Elite — Premium Coverage Details", "domain": "home_insurance", "source": "home_insurance_kb.json", "content": "Question: What does Home Protector Elite cover that Basic does not?\nAnswer: Elite adds: New-for-Old settlement (no depreciation on contents/building), Building up to ₹2 Crore, Contents up to ₹25L, Jewellery up to ₹10L, Fine art ₹5L, Gadgets ₹3L worldwide, Sneak theft, Appliance breakdown (₹1L/yr without accident), Personal liability ₹25L, Global contents cover, Data recovery ₹25K, Architects fees, Debris removal, Rent loss ₹50K/month, and Temp accommodation ₹60K."}, {"score": 0.676, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "home_insurance", "source": "home_protector_elite_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Home Protector Elite** is the flagship, ultra-comprehensive home insurance plan from SecureShield — crafted for homeowners with high-value properties, luxury interiors, premium electronics, jewellery, art collections, and complete peace of mind requirements. This plan covers everything in the Basic plan and significantly extends protection to include jewellery, global contents cover, rent-loss liability, gadget cover, and a superior reinstatement value basis for all settlements."}], "customer_id": "9b121278-c52d-4e14-821a-89b97dbf7d90", "passage_count": 4}', 'success', 484, '2026-09-21T06:07:57.030971+00:00') ON CONFLICT ("exec_id") DO NOTHING;
INSERT INTO "tool_execution" ("exec_id", "conversation_id", "tool_name", "input_params", "output", "status", "duration_ms", "timestamp") VALUES ('ac3f1c08-f918-4fc6-9580-8bc2920ca949'::uuid, 'f1013c1b-2130-4023-aff5-75c2201bd2dc'::uuid, 'get_policy_coverage', '{"query": "can you provide details about the coverage of my insurance policy", "customer_id": "c3cba623-b8a7-41fe-b9b6-8fd36e132b81"}', '{"plan": "Health Shield Basic", "found": true, "message": "Policy coverage details retrieved for Health Shield Basic from knowledge base.", "passages": [{"score": 0.739, "title": "Health Shield Basic Policy — General Terms", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[Health Shield Basic Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}, {"score": 0.691, "title": "Health Shield Premium Policy — General Terms", "domain": "health_insurance", "source": "health_shield_premium_policy.md", "content": "[Health Shield Premium Policy — General Terms]\n# SECURESHIELD HEALTH INSURANCE COMPANY LIMITED"}, {"score": 0.689, "title": "POLICY OVERVIEW & SPECIALTY", "domain": "health_insurance", "source": "health_shield_basic_policy.md", "content": "[POLICY OVERVIEW & SPECIALTY]\n**Health Shield Basic** is an affordable entry-level individual and family health indemnity plan designed for first-time insurance buyers, young professionals, and price-conscious families. It covers essential inpatient hospitalization expenses with straightforward terms and a wide cashless hospital network.\n\n**Key Specialty:**\n- Low-cost quarterly premium with no annual lump-sum burden\n- Covers all major acute and chronic illnesses after applicable waiting periods"}, {"score": 0.672, "title": "Health Shield Basic — Coverage Details", "domain": "health_insurance", "source": "health_shield_plans_kb.json", "content": "Question: What does Health Shield Basic cover?\nAnswer: Health Shield Basic covers inpatient hospitalization (24+ hours), room rent up to ₹1,500/day, ICU up to ₹3,000/day, 30-day pre-hospitalization, 60-day post-hospitalization, 200+ day care procedures, and emergency ambulance up to ₹1,500. Sum insured: ₹2L (individual) or ₹3L (family floater). 20% co-pay applies."}], "customer_id": "c3cba623-b8a7-41fe-b9b6-8fd36e132b81", "passage_count": 4}', 'success', 250, '2026-09-21T06:43:31.163982+00:00') ON CONFLICT ("exec_id") DO NOTHING;
